    public static bool TryGet(string name, out string value) => Table.Value.TryGetValue(name, out value!);

    private static Dictionary<string, string> Build()
    {
        var table = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var chunk in Data)
        {
            foreach (var line in chunk.Split('\n'))
            {
                var space = line.IndexOf(' ', StringComparison.Ordinal);
                var codes = line[(space + 1)..].Split(',').Select(c => char.ConvertFromUtf32(Convert.ToInt32(c, 16)));
                table[line[..space]] = string.Concat(codes);
            }
        }

        return table;
    }
